'use client';
import { useState } from 'react';
import { AnimatePresence, motion, useReducedMotion } from 'motion/react';
import { Plus, ArrowUpRight } from 'lucide-react';
const capabilities=[{title:'Interface design',copy:'Clear hierarchy, considered layouts, and components that work together. I turn complex requirements into interfaces people can navigate with confidence.',tags:['Figma','Prototyping','Design systems']},{title:'Frontend engineering',copy:'Responsive interfaces and reusable components, built with TypeScript and a careful approach to architecture. Good design deserves equally thoughtful implementation.',tags:['React','Next.js','TypeScript','Tailwind CSS']},{title:'Motion & interaction',copy:'Motion gives an interface rhythm and helps every action feel connected. From a tiny hover state to a choreographed page, I care about how it feels to use.',tags:['GSAP','Motion','Creative development']},{title:'The final 10%',copy:'Refining performance, keyboard access, responsive behavior, and the details that make an experience hold together across screens.',tags:['Accessibility','Performance','Design QA']}];
export function About(){const [open,setOpen]=useState(0);const reduced=useReducedMotion();return <div className="about-grid"><div className="about-bio reveal"><span className="eyebrow">02 / THE PERSON BEHIND THE PIXELS</span><h2>A designer’s eye.<br/>An engineer’s mind.</h2><p>I’m Gerald Donkor, a design engineer based in Ghana. I work in the space between how something looks and how it works.</p><p>I design and build polished, interactive web experiences—bringing thoughtful interfaces, expressive motion, and strong frontend engineering together.</p><a href="https://github.com/gerald-donkor" target="_blank" rel="noreferrer">A little more about me on GitHub <ArrowUpRight size={17}/></a><div className="bio-note"><span>MY DEFAULT SETTING</span><strong>Building with taste :)</strong></div></div><div className="capabilities reveal">{capabilities.map((c,i)=><div className={'capability '+(i===open?'is-open':'')} key={c.title}><button onClick={()=>setOpen(open===i?-1:i)} aria-expanded={open===i} aria-controls={'cap-'+i}><span className="cap-number">0{i+1}</span><h3>{c.title}</h3><Plus size={20}/></button><AnimatePresence initial={false}>{open===i&&<motion.div id={'cap-'+i} initial={{height:0,opacity:0}} animate={{height:'auto',opacity:1}} exit={{height:0,opacity:0}} transition={{duration:reduced?0:.3}} className="cap-content"><p>{c.copy}</p><div className="tag-list">{c.tags.map(t=><span key={t}>{t}</span>)}</div></motion.div>}</AnimatePresence></div>)}</div></div>}
